  const WEAPON_LEVEL_COSTS = Object.freeze([100, 250, 500, 900]);
  const BASE_WEAPON_MAX_LEVEL = 5;

  function weaponMaxLevelForMaps(unlockedMaps = ["backyard"]) {
    const mapCount = unlockedMaps instanceof Set
      ? unlockedMaps.size
      : Array.isArray(unlockedMaps) ? new Set(unlockedMaps).size : 1;
    return BASE_WEAPON_MAX_LEVEL + Math.max(0, mapCount - 1);
  }

  function weaponUpgradeCost(currentLevel) {
    const configuredCost = WEAPON_LEVEL_COSTS[currentLevel - 1];
    if (configuredCost != null) return configuredCost;
    const extraLevel = currentLevel - WEAPON_LEVEL_COSTS.length;
    return WEAPON_LEVEL_COSTS.at(-1) + extraLevel * 500 + extraLevel * (extraLevel + 1) * 50;
  }


  function totalContactDamage(enemies) {
    return enemies.reduce((total, enemy) => {
      const damage = Number.isFinite(enemy.damage) ? Math.max(0, enemy.damage) : 0;
      return total + damage;
    }, 0);
  }

  function nearestBounceTarget(projectile, enemies, excludedEnemy) {
    let nearest = null;
    let nearestDistance = Infinity;
    for (const enemy of enemies) {
      if (!enemy.active || enemy.targetable === false || enemy === excludedEnemy || projectile.hitEnemies.has(enemy)) continue;
      const distance = Math.hypot(enemy.x - projectile.x, enemy.y - projectile.y);
      if (distance < nearestDistance) {
        nearest = enemy;
        nearestDistance = distance;
      }
    }
    return nearest;
  }

  function applyKnockback(enemy, sourceX, sourceY, amount, bounds = null) {
    if (!amount || enemy.isBoss) return;
    const offsetX = enemy.x - sourceX;
    const offsetY = enemy.y - sourceY;
    const length = Math.hypot(offsetX, offsetY) || 1;
    enemy.x += offsetX / length * amount;
    enemy.y += offsetY / length * amount;
    if (bounds) {
      enemy.x = Math.max(enemy.radius, Math.min(bounds.width - enemy.radius, enemy.x));
      enemy.y = Math.max(enemy.radius, Math.min(bounds.height - enemy.radius, enemy.y));
    }
  }

  function applyFire(enemy, damagePerSecond = 5, duration = 10, maxStacks = 1) {
    enemy.fireTime = Math.max(enemy.fireTime ?? 0, duration);
    enemy.fireDamagePerStack = Math.max(enemy.fireDamagePerStack ?? 0, damagePerSecond);
    const currentStacks = Math.max(0, enemy.fireStacks ?? 0);
    enemy.fireStacks = maxStacks > 1
      ? Math.min(maxStacks, currentStacks + 1)
      : Math.max(1, currentStacks);
    enemy.fireDamagePerSecond = enemy.fireDamagePerStack * enemy.fireStacks;
  }

  function applyFreeze(enemy, duration = 2) {
    enemy.freezeTime = Math.max(enemy.freezeTime ?? 0, duration);
  }

  function updateEnemyStatus(enemy, deltaTime) {
    const frozen = (enemy.freezeTime ?? 0) > 0;
    enemy.freezeTime = Math.max(0, (enemy.freezeTime ?? 0) - deltaTime);
    const burningTime = Math.min(deltaTime, enemy.fireTime ?? 0);
    const fireDamage = burningTime * (enemy.fireDamagePerSecond ?? 0);
    enemy.fireTime = Math.max(0, (enemy.fireTime ?? 0) - deltaTime);
    if (enemy.fireTime === 0) {
      enemy.fireDamagePerSecond = 0;
      enemy.fireDamagePerStack = 0;
      enemy.fireStacks = 0;
    }
    return { frozen, fireDamage };
  }



